@org.springframework.transaction.annotation.Transactional(readOnly = true)
public java.util.Mapp<String, Object> getStatus(String shortCode) {
    java.util.Optional<ShortUrl> shortUrlOptional = repository.findByShortCode(shortCode);
    if (shortUrlOptional.isEmpty()) {
        throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND, "Short URL not found");
    }
    ShortUrl shortUrl = shortUrlOptional.get();
    boolean expired = shortUrl.isExpired(java.time.Instant.now());
    return java.util.Map.of("shortCode", shortCode, "expired", expired);
}

